import { createRequire } from "module";
import fs from "fs";
const require = createRequire(import.meta.url);

function loadApi(file) {
  const src = fs.readFileSync(file, "utf8");
  const js = ts.transpileModule(src, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 },
  }).outputText;
  const mod = { exports: {} };
  new Function("exports", "module", "require", js)(mod.exports, mod, require);
  return mod.exports;
}

const orig = loadApi("process_batch.orig.ts");

// test inputs
const chans = ["A", "B", ""];
const units = ["uV", "mV", "V", "X"];
const values = [-100, -1, 0, 1, 49, 50, 199, 200, 599, 600, 899, 900, 1000, 2000000, 42.5, "x", null, undefined];
const ats = [0, 1, 55, 1.5, -1, "1", null];

const inputs = [];
inputs.push(undefined, null, 5, "str", [], {});
inputs.push({ readings: "nope" }, { readings: [] }, { readings: [1, 2, 3] });
inputs.push({ readings: [Math.random(), ...Array(501).fill(0)] });

function genReading(i) {
  return {
    channel: chans[i % chans.length],
    unit: units[i % units.length],
    value: values[i % values.length],
    at: ats[i % ats.length],
  };
}
// build a variety of batches
for (let n = 1; n <= 8; n++) {
  const readings = [];
  for (let i = 0; i < n; i++) {
    readings.push(genReading(i * 3));
  }
  inputs.push({ readings });
}
// all-valid batch
inputs.push({ readings: [
  { channel: "A", unit: "V", value: 0.5, at: 0 },
  { channel: "A", unit: "mV", value: 300, at: 10 },
  { channel: "B", unit: "uV", value: 200000, at: 20 },
  { channel: "C", unit: "mV", value: 950, at: 30 },
  { channel: "B", unit: "mV", value: -5, at: 40 },
  { channel: "A", unit: "V", value: 0.05, at: 50 },
]});
// extreme uV conversion
inputs.push({ readings: [
  { channel: "A", unit: "uV", value: 999, at: 0 },
  { channel: "A", unit: "uV", value: 1000, at: 1 },
  { channel: "A", unit: "uV", value: 1001, at: 2 },
  { channel: "A", unit: "uV", value: 0, at: 3 },
  { channel: "B", unit: "V", value: 2, at: 4 },
  { channel: "C", unit: "mV", value: 900, at: 5 },
]});

let pass = 0, fail = 0;
function norm(x) { return JSON.stringify(x); }
for (const inp of inputs) {
  const a = orig.processBatch(inp);
  const b = orig.processBatch(JSON.parse(JSON.stringify(inp))); // clone to be safe
  // Just report orig output; comparison done after new impl
  if (norm(a) !== norm(b)) { console.log("internal inconsistency", norm(a), norm(b)); }
}
console.log("inputs generated:", inputs.length);
fs.writeFileSync("inputs.json", JSON.stringify(inputs));

