function genReading(i) {
  return {
    channel: chans[i % chans.length],
    unit: units[i % units.length],
    value: values[i % values.length],
    at: ats[i % ats.length],
  };
}
// build a variety of batches
for (let n = 1; n <= 8; n++) {
