const ts = require('typescript');
const fs = require('fs');

function loadApi(file) {
  const src = fs.readFileSync(file, 'utf8');
  const js = ts.transpileModule(src, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 } }).outputText;
  const mod = { exports: {} };
  new Function('exports','module','require', js)(mod.exports, mod, require);
  return mod.exports;
}

const orig = loadApi('process_batch.orig.ts');
const inputs = JSON.parse(fs.readFileSync('inputs.json', 'utf8'));
const norm = (x) => JSON.stringify(x);
let pass = 0, fail = 0;
const failures = [];

// base outputs from orig
const base = [];
for (const inp of inputs) {
  base.push(orig.processBatch(JSON.parse(JSON.stringify(inp))));
}

// now load candidate and compare
for (const file of process.argv.slice(2)) {
  const cand = loadApi(file);
  let p = 0, f = 0;
  const fl = [];
  for (let i = 0; i < inputs.length; i++) {
    const a = base[i];
    const b = cand.processBatch(JSON.parse(JSON.stringify(inputs[i])));
    if (norm(a) === norm(b)) p++; else { f++; fl.push({ idx: i, input: inputs[i], orig: a, cand: b }); }
  }
  console.log(`\n=== ${file} ===`);
  console.log("PASS", p, "FAIL", f);
  for (const fl_ of fl.slice(0, 20)) {
    console.log("  FAIL idx", fl_.idx);
    console.log("    input:", JSON.stringify(fl_.input));
    console.log("    orig :", JSON.stringify(fl_.orig));
    console.log("    cand :", JSON.stringify(fl_.cand));
  }
}

