  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

/** Ordered signal classes; rank reflects how severe a reading is. */
const SEVERITY: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

export function processBatch(raw: unknown): BatchResult {
  const validationError = validateBatch(raw);
  if (validationError !== null) {
    return { ok: false, error: validationError };
  }

  const entries = (raw as { readings: unknown[] }).readings;

  const parsed: ParsedReading[] = [];
  const labels: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  const alerts: string[] = [];
  let worstLabel = "standby";

  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (isError(outcome)) {
      return { ok: false, error: outcome };
    }

    const millivolts = normalizeValue(outcome.unit, outcome.value);
    parsed.push({ channel: outcome.channel, millivolts, at: outcome.at });

    const label = classifySignal(millivolts);
    labels.push(label);
    accumulateSummary(channels, outcome.channel, millivolts, label);

    if (severityRank(label) > severityRank(worstLabel)) {
      worstLabel = label;
    }

    const alertClass = alertForMillivolts(millivolts);
    if (alertClass !== null) {
      alerts.push(outcome.channel + ":" + alertClass);
    }
  }

  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, worstLabel);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

